func Grep(path, pattern string) error {
	file, err := os.Open(path)
	if err != nil {
		return err
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	lineNum := 1

	for scanner.Scan() {
		line := scanner.Text()
		if strings.Contains(line, pattern) {
			fmt.Printf("%s:%d: %s\n", path, lineNum, line)
		}
		lineNum++
	}

	return scanner.Err()
}

